import jinja2
from markupsafe import Markup

def test_jinja2_markupsafe_compatibility():
    template = jinja2.Template('Hello {{ name }}!')
    assert template.render(name='World') == 'Hello World!'
    assert str(Markup('<b>Bold</b>')) == '<b>Bold</b>'
